/**
 * Turns one decoded template-generation stream event into a DOM update:
 * which activity row lights up, which item of the progress list is added or
 * closed, and which phase label shows. generation_watch.js decodes the stream
 * and calls this for each event; generation_stream.js owns the phase label itself and passes
 * `paintStage` in rather than this module importing it, so the two never
 * import each other.
 *
 * @module     local_coursegen/local/courseai/template/generation_events
 * @copyright  2026 Wilber Narvaez <https://datacurso.com>
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

import {
    addActivity,
    closeActivity,
    failActivity,
    openChecklist,
    showAddedStructure,
    showUnitCopies,
    showRepeatProgress,
} from 'local_coursegen/local/courseai/template/generation_checklist';
import {showWorkingIndicator} from 'local_coursegen/local/courseai/ui/feedback-progress';
import {createRepeatTracker} from 'local_coursegen/local/courseai/template/repeat_progress';
import {resetStatus, showNotice} from 'local_coursegen/local/courseai/template/generation_status';
import {markImagesTotalKnown, onPicture} from 'local_coursegen/local/courseai/template/images_panel';

const repeats = createRepeatTracker();

/** The status classes the shared generation stylesheet reacts to. */
export const STATUS_CLASS = {
    pending: 'cg-gen-pending',
    running: 'cg-gen-active',
    done: 'cg-gen-done',
};
export const ALL_STATUS_CLASSES = Object.values(STATUS_CLASS);

/**
 * Mark one activity row with the state its generation is in.
 *
 * @param {string} uid
 * @param {string} status A key of STATUS_CLASS.
 */
export const markRow = (uid, status) => {
    const row = document.querySelector(`[data-generation-uid="${uid}"]`);
    if (!row) {
        return;
    }
    row.classList.remove(...ALL_STATUS_CLASSES);
    row.classList.add(STATUS_CLASS[status] || STATUS_CLASS.pending);
};

/**
 * Reset the progress counters for a phase that is starting over.
 *
 * @param {Object} progress Mutable {total, done} counters.
 * @param {Object} data
 */
const resetProgress = (progress, data) => {
    progress.total = Math.max(0, Number(data.total) || 0);
    progress.done = 0;
    progress.doneUids = new Set();
};

/**
 * Count one finished activity once: the same activity is never counted twice, whatever the stream repeats.
 *
 * @param {string} uid
 * @param {Object} progress Mutable {total, done, doneUids} counters.
 * @returns {boolean} Whether it was not counted before.
 */
const countDone = (uid, progress) => {
    if (!(progress.doneUids instanceof Set)) {
        progress.doneUids = new Set();
    }
    if (progress.doneUids.has(uid)) {
        return false;
    }
    progress.doneUids.add(uid);
    progress.done = progress.doneUids.size;
    return true;
};

/**
 * The review lists every activity the run wrote: it is what the count shows, even when the stream that told each one
 * was cut and some of their events never arrived (the run went on and was reached again).
 *
 * @param {Object} data A review_needed event with its generated_activities.
 * @param {Object} progress Mutable {total, done, doneUids} counters.
 * @returns {string} 'review'
 */
const reviewActivities = (data, progress) => {
    const written = (Array.isArray(data.generated_activities) ? data.generated_activities : [])
        .filter((activity) => activity && activity.uid);
    progress.total = Math.max(Number(progress.total) || 0, written.length);
    for (const activity of written) {
        const uid = String(activity.uid);
        if (countDone(uid, progress)) {
            markRow(uid, 'done');
            closeActivity(uid, progress);
        }
    }
    return 'review';
};

/**
 * One activity's generation failed or finished; count it and, once every
 * activity is accounted for, move the header on to the next phase.
 *
 * @param {Object} data
 * @param {Object} progress Mutable {total, done} counters.
 * @param {Function} paintStage Shows one phase label, by key.
 * @returns {string} ''
 */
const finishActivity = (data, progress, paintStage) => {
    markRow(data.uid, 'done');
    if (countDone(String(data.uid), progress)) {
        closeActivity(data.uid, progress);
    }
    if (progress.total > 0 && progress.done >= progress.total) {
        paintStage('saving');
    }
    return '';
};

/**
 * One activity's generation failed: it stops looking "in progress", but it is not done, so it carries no check, it is
 * not counted and the header does not move on to saving: the run itself then fails, and a retry makes what is missing.
 *
 * @param {Object} data
 * @param {Object} progress Mutable {total, done} counters.
 * @returns {string} ''
 */
const failActivityRow = (data, progress) => {
    markRow(data.uid, 'pending');
    failActivity(data.uid, progress);
    return '';
};

/**
 * Show on the row of an activity how far its repeat blocks have got.
 *
 * @param {string} uid
 */
const reportRepeats = (uid) => {
    const summary = repeats.summary(uid);
    if (summary) {
        showRepeatProgress(uid, summary);
    }
};

/** The stages that start once every activity is written, when the number of pictures is final. */
const TOTAL_FINAL_STAGES = ['activity_images', 'saving'];

/** One handler per stream event type, keyed the way the server names them. */
const EVENT_HANDLERS = {
    template_stage: (data, progress, paintStage) => {
        resetStatus();
        paintStage(data.stage);
        // Once every activity is written no new picture can appear: the images pill shows its final total.
        if (TOTAL_FINAL_STAGES.includes(data.stage)) {
            markImagesTotalKnown();
        }
        return '';
    },
    // The line under the header's title is often scrolled out of sight on the right panel: what the person
    // must not miss goes to the status bar of the thread too, which is always in view.
    template_notice: (data) => {
        showNotice(data).then((text) => text && showWorkingIndicator({}, text)).catch(() => undefined);
        return '';
    },
    template_image: (data) => {
        // The pictures are counted and listed by the images pill only, with readable names.
        onPicture(data);
        return '';
    },
    // What the guideline added after the template's own sections joins the structure on the right, and so the list.
    template_structure: (data) => {
        showAddedStructure(data);
        return '';
    },
    // The copies of the template section, one per unit of the syllabus, are drawn after the section they repeat.
    template_unit_copies: (data) => {
        showUnitCopies(data);
        return '';
    },
    review_needed: reviewActivities,
    activity_progress_init: (data, progress, paintStage) => {
        resetStatus();
        repeats.reset();
        resetProgress(progress, data);
        openChecklist(progress);
        paintStage('activities');
        return '';
    },
    activity_progress_start: (data) => {
        markRow(data.uid, 'running');
        addActivity(data);
        return '';
    },
    activity_repeat_plan: (data) => {
        repeats.plan(data.uid, data.block, data.total, data.names);
        reportRepeats(data.uid);
        return '';
    },
    activity_repeat_progress: (data) => {
        repeats.progress(data.uid, data.block, data.done, data.total, data.last);
        reportRepeats(data.uid);
        return '';
    },
    activity_progress_done: finishActivity,
    activity_progress_failed: failActivityRow,
    // The AI has questions before it starts: the pass ends so they can be answered, as it does for the review.
    questions: () => 'questions',
    questions_answered: () => '',
    completed: () => 'completed',
    failed: () => 'failed',
};

/**
 * Apply one decoded stream event.
 *
 * @param {Object} data
 * @param {Object} progress Mutable {total, done} counters.
 * @param {Function} paintStage Shows one phase label, by key.
 * @returns {string} '' to keep listening, otherwise 'review'/'questions'/'completed'/'failed'.
 */
export const applyEvent = (data, progress, paintStage) => {
    const handler = EVENT_HANDLERS[data.type];
    if (!handler) {
        return '';
    }
    return handler(data, progress, paintStage);
};
